+function Get-Factorial {
+    <#
+    .SYNOPSIS
+    Returns the factorial of N.
+
+    .PARAMETER N
+    A non-negative integer. By definition, 0! and 1! both return 1.
+
+    .OUTPUTS
+    System.Numerics.BigInteger
+    #>
+    [CmdletBinding()]
+    param(
+        [Parameter(Mandatory)]
+        [ValidateRange(0, [int]::MaxValue)]
+        [int] $N
+    )
+
+    $result = [System.Numerics.BigInteger] 1
+    for ($i = 2; $i -le $N; $i++) {
+        $result *= $i
+    }
+
+    return $result
+}
